#include "config.h"
#include "beam.h"
#include "channel.h"
#include "trajectory.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static const char *state_name(NodeTRState s){return s==NODE_TX?"TX":"RX";}
static void run(SimConfig *c,double t){printf("\n===== t=%.3f s =====\n",t);for(size_t i=0;i<c->nn;i++){Node *n=&c->nodes[i];NodePosition *p=find_pos(c,n->id);if(!p||!update_state(n,p,t))continue;printf("Node %d %-8s state=%s GEO=(%.8f,%.8f,%.2f m) ECEF=(%.3f,%.3f,%.3f) velocity=(%.4f,%.4f,%.4f) NED attitude=(%.2f,%.2f,%.2f) deg\n",n->id,n->name,state_name(n->tr_state),p->geodetic.latitude_deg,p->geodetic.longitude_deg,p->geodetic.altitude_m,p->position.x,p->position.y,p->position.z,n->velocity.x,n->velocity.y,n->velocity.z,n->attitude.heading,n->attitude.pitch,n->attitude.roll);}
for(size_t i=0;i<c->nn;i++)for(size_t j=i+1;j<c->nn;j++){Node *a=&c->nodes[i],*b=&c->nodes[j];if(!a->enabled||!b->enabled||a->tr_state==b->tr_state)continue;Node *tx=a->tr_state==NODE_TX?a:b,*rx=a->tr_state==NODE_RX?a:b;NodePosition *tp=find_pos(c,tx->id),*rp=find_pos(c,rx->id);if(!tp||!rp)continue;printf("\n[Link %d -> %d]\n",tx->id,rx->id);for(size_t ta=0;ta<tx->array_count;ta++){if(tx->tx_array_id>=0&&tx->arrays[ta].id!=tx->tx_array_id)continue;for(size_t ra=0;ra<rx->array_count;ra++){ChannelResult r=channel(c,tx,tp,rx,rp,&tx->arrays[ta],&rx->arrays[ra],t);TriNodesCalResult_Update(&g_tri_nodes_cal_result,&r);print_channel(r);}}}}
int main(int argc,char **argv){const char *ini="config/simulation.ini";double requested=0;int once=0;for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--time")&&i+1<argc){requested=strtod(argv[++i],NULL);once=1;}else if(!strcmp(argv[i],"--help")){puts("Usage: channel_sim [config.ini] [--time seconds]");return 0;}else ini=argv[i];}SimConfig *c=calloc(1,sizeof(*c));if(!c)return 1;if(!config_load(c,ini)){fprintf(stderr,"Cannot load configuration: %s\n",ini);free(c);return 1;}if(!BeamTable_InitAllNodes(&g_beam_cache,c->nodes,(uint16_t)c->nn)){fprintf(stderr,"Beam table initialization failed\n");config_free(c);free(c);return 1;}TriNodesCalResult_Init(&g_tri_nodes_cal_result);printf("Loaded %zu node(s); geometry in ECEF, attitude input in NED.\n",c->nn);if(once)run(c,requested);else for(double t=c->start;t<=c->end+1e-9;t+=c->step)run(c,t);printf("\nGlobal result records: %zu\n",g_tri_nodes_cal_result.count);config_free(c);free(c);return 0;}
